  v_derivation constant text := 'manual_curation:official_aces_and_wnba_results';
  v_rows constant jsonb := '[{"game_date":"2024-05-14","away":"Phoenix Mercury","away_code":"phx","away_points":80,"home":"Las Vegas Aces","home_code":"lva","home_points":89,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-05-18","away":"Los Angeles Sparks","away_code":"las","away_points":82,"home":"Las Vegas Aces","home_code":"lva","home_points":89,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-05-21","away":"Phoenix Mercury","away_code":"phx","away_points":98,"home":"Las Vegas Aces","home_code":"lva","home_points":88,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-05-25","away":"Indiana Fever","away_code":"ind","away_points":80,"home":"Las Vegas Aces","home_code":"lva","home_points":99,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-05-29","away":"Las Vegas Aces","away_code":"lva","away_points":80,"home":"Minnesota Lynx","home_code":"min","home_points":66,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-05-31","away":"Las Vegas Aces","away_code":"lva","away_points":74,"home":"Atlanta Dream","home_code":"atl","home_points":78,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-06-05","away":"Las Vegas Aces","away_cod