tage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-06-21","away":"Connecticut Sun","away_code":"con","away_points":74,"home":"Las Vegas Aces","home_code":"lva","home_points":85,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-06-27","away":"Las Vegas Aces","away_code":"lva","away_points":95,"home":"Chicago Sky","home_code":"chi","home_points":83,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-06-29","away":"Las Vegas Aces","away_code":"lva","away_points":88,"home":"Washington Mystics","home_code":"was","home_points":77,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-07-02","away":"Indiana Fever","away_code":"ind","away_points":69,"home":"Las Vegas Aces","home_code":"lva","home_points":88,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-07-04","away":"Washington Mystics","away_code":"was","away_points":77,"home":"Las Vegas Aces","home_code":"lva","home_points":98,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-07-05","away":"Las Vegas Aces","away_code":"lva","away_points":93,"home":"Los Angeles Sparks","home_code":"las","home_points":98,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":1,"source_key":"aces_sep19_notes"},{"game_date":"2024-07-07","away":"Dallas Wings","away_code":"dal","away_points":85,"home":"Las Vegas Aces","home_code":"lva","home_points":104,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-07-10","away":"Las Vegas Aces","away_code":"lva","away_points":84,"home":"Seattle Storm","home_code":"sea","home_points":79,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-07-12","away":"Las Vegas Aces","away_code":"lva","away_points":84,"home":"Atlanta Dream","home_code":"atl","home_points":70,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-07-14","away":"Las Vegas Aces","away_code":"lva","away_points":89,"home":"Washington Mystics","home_code":"was","home_points":77,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-07-16","away":"Chicago Sky","away_code":"chi","away_points":93,"home":"Las Vegas Aces","home_code":"lva","home_points":85,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-08-17","away":"New York Liberty","away_code":"nyl","away_points":79,"home":"Las Vegas Aces","home_code":"lva","home_points":67,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"wnba_aug17"},{"game_date":"2024-08-18","away":"Los Angeles Sparks","away_code":"las","away_points":71,"home":"Las Vegas Aces","home_code":"lva","home_points":87,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-08-21","away":"Minnesota Lynx","away_code":"min","away_points":98,"home":"Las Vegas Aces","home_code":"lva","home_points":87,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"wnba_aug21"},{"game_date":"2024-08-23","away":"Las Vegas Aces","away_code":"lva","away_points":74,"home":"Minnesota Lynx","home_code":"min","home_points":87,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-08-25","away":"Las Vegas Aces","away_code":"lva","away_points":77,"home":"Chicago Sky","home_code":"chi","home_points":75,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-08-27","away":"Las Vegas Aces","away_code":"lva","away_points":90,"home":"Dallas Wings","home_code":"dal","home_points":93,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-08-30","away":"Atlanta Dream","away_code":"atl","away_points":72,"home":"Las Vegas Aces","home_code":"lva","home_points":83,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-09-01","away":"Las Vegas Aces","away_code":"lva","away_points":97,"home":"Phoenix Mercury","home_code":"phx","home_points":79,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-09-03","away":"Chicago Sky","away_code":"chi","away_points":71,"home":"Las Vegas Aces","home_code":"lva","home_points":90,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-09-06","away":"Las Vegas Aces","away_code":"lva","away_points":72,"home":"Connecticut Sun","home_code":"con","home_points":67,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-09-08","away":"Las Vegas Aces","away_code":"lva","away_points":71,"home":"New York Liberty","home_code":"nyl","home_points":75,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-09-11","away":"Las Vegas Aces","away_code":"lva","away_points":86,"home":"Indiana Fever","home_code":"ind","home_points":75,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-09-13","away":"Las Vegas Aces","away_code":"lva","away_points":78,"home":"Indiana Fever","home_code":"ind","home_points":74,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-09-15","away":"Connecticut Sun","away_code":"con","away_points":71,"home":"Las Vegas Aces","home_code":"lva","home_points":84,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-09-17","away":"Las Vegas Aces","away_code":"lva","away_points":85,"home":"Seattle Storm","home_code":"sea","home_points":72,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"aces_sep19_notes"},{"game_date":"2024-09-19","away":"Dallas Wings","away_code":"dal","away_points":84,"home":"Las Vegas Aces","home_code":"lva","home_points":98,"stage_id":"wnba_2024_regular_season","game_type":"regular","season_phase":"regular_season","counts_for_standings":true,"overtime_periods":0,"source_key":"wnba_sep19"},{"game_date":"2024-09-22","away":"Seattle Storm","away_code":"sea","away_points":67,"home":"Las Vegas Aces","home_code":"lva","home_points":78,"stage_id":"wnba_2024_playoffs","game_type":"playoff","season_phase":"playoffs","counts_for_standings":false,"overtime_periods":0,"source_key":"aces_year_review"},{"game_date":"2024-09-24","away":"Seattle Storm","away_code":"sea","away_points":76,"home":"Las Vegas Aces","home_code":"lva","home_points":83,"stage_id":"wnba_2024_playoffs","game_type":"playoff","season_phase":"playoffs","counts_for_standings":false,"overtime_periods":0,"source_key":"aces_year_review"},{"game_date":"2024-09-29","away":"Las Vegas Aces","away_code":"lva","away_points":77,"home":"New York Liberty","home_code":"nyl","home_points":87,"stage_id":"wnba_2024_playoffs","game_type":"playoff","season_phase":"playoffs","counts_for_standings":false,"overtime_periods":0,"source_key":"aces_year_review"},{"game_date":"2024-10-01","away":"Las Vegas Aces","away_code":"lva","away_points":84,"home":"New York Liberty","home_code":"nyl","home_points":88,"stage_id":"wnba_2024_playoffs","game_type":"playoff","season_phase":"playoffs","counts_for_standings":false,"overtime_periods":0,"source_key":"aces_year_review"},{"game_date":"2024-10-04","away":"New York Liberty","away_code":"nyl","away_points":81,"home":"Las Vegas Aces","home_code":"lva","home_points":95,"stage_id":"wnba_2024_playoffs","game_type":"playoff","season_phase":"playoffs","counts_for_standings":false,"overtime_periods":0,"source_key":"aces_year_review"},{"game_date":"2024-10-06","away":"New York Liberty","away_code":"nyl","away_points":76,"home":"Las Vegas Aces","home_code":"lva","home_points":62,"stage_id":"wnba_2024_playoffs","game_type":"playoff","season_phase":"playoffs","counts_for_standings":false,"overtime_periods":0,"source_key":"aces_year_review"}]'::jsonb;
  r record;
  v_game_id text;
  v_doc uuid;
  v_existing_run integer;
  v_preexisting integer;
  v_new_games integer := 0;
  v_corroborations integer := 0;
  v_evidence integer;
begin
  perform public.wbh_assert_ingestible('pbe_curation');

  select count(*) into v_existing_run from public.wbh_ingestion_runs where scope->>'dataset'=v_dataset and status='ok';
  if v_existing_run > 0 then
    if (select count(*) from public.wbh_game_result_evidence e join public.wbh_ingestion_runs ir on ir.run_id=e.ingestion_run_id where ir.scope->>'dataset'=v_dataset)=46
       and (select count(*) from public.wbh_games g join public.wbh_game_teams gt on gt.game_id=g.game_id where g.edition_id='wnba_2024' and gt.team_edition_id='te_las_vegas_aces_2024')=46 then return; end if;
    raise exception 'wbh: Aces 2024 result run exists but verification is incomplete' using errcode='P0001';
  end if;

  select count(*) into v_preexisting
    from jsonb_to_recordset(v_rows) as x(game_date date,away text,away_code text,away_points integer,home text,home_code text,home_points integer,stage_id text,game_type text,season_phase text,counts_for_standings boolean,overtime_periods integer,source_key text)
    join public.wbh_games g on g.game_id='gm_wnba_2024_'||to_char(x.game_date,'YYYYMMDD')||'_'||x.away_code||'_at_'||x.home_code;
  if v_preexisting <> 4 then raise exception 'wbh: expected exactly 4 Indiana-overlap Aces games before load, found %',v_preexisting using errcode='P0001'; end if;

  insert into public.wbh_source_documents (source_id,source_record_id,request_url,request_method,retrieved_at,http_status,content_sha256,content_type,byte_size,storage_state,transformation_version,notes)
  values ('pbe_curation','aces_2024_schedule_results_through_20240917','https://cdn.wnba.com/sites/1611661319/2024/09/2024-09-19-Aces-vs-Dallas-Game-Notes-FINALL.pdf','GET',v_now,200,
    encode(extensions.digest(convert_to((select jsonb_agg(x order by x.game_date)::text from jsonb_to_recordset(v_rows) as x(game_date date,away text,away_code text,away_points integer,home text,home_code text,home_points integer,stage_id text,game_type text,season_phase text,counts_for_standings boolean,overtime_periods integer,source_key text) where source_key='aces_sep19_notes'),'UTF8'),'sha256'),'hex'),
    'application/json',null,'hash_only','wbh_manual_game_results_v1','Normalized factual results manually curated from official Las Vegas Aces Sept. 19, 2024 game notes. Known schedule-table typos on Aug. 17 and Aug. 21 are excluded and resolved from official WNBA game pages.') returning document_id into v_doc_notes;

  insert into public.wbh_source_documents (source_id,source_record_id,request_url,request_method,retrieved_at,http_status,content_sha256,content_type,byte_size,storage_state,transformation_version,notes)
  values ('pbe_curation','wnba_game_1022400156','https://www.wnba.com/game/nyl-vs-lva-1022400156','GET',v_now,200,encode(extensions.digest(convert_to('2024-08-17|New York Liberty|79|Las Vegas Aces|67','UTF8'),'sha256'),'hex'),'text/plain',null,'hash_only','wbh_manual_game_results_v1','Official WNBA game page resolves the Aces game-notes score-order typo.') returning document_id into v_doc_aug17;

  insert into public.wbh_source_documents (source_id,source_record_id,request_url,request_method,retrieved_at,http_status,content_sha256,content_type,byte_size,storage_state,transformation_version,notes)
  values ('pbe_curation','wnba_game_1022400166','https://www.wnba.com/game/min-vs-lva-1022400166','GET',v_now,200,encode(extensions.digest(convert_to('2024-08-21|Minnesota Lynx|98|Las Vegas Aces|87','UTF8'),'sha256'),'hex'),'text/plain',null,'hash_only','wbh_manual_game_results_v1','Official WNBA game page resolves the Aces game-notes score-order typo.') returning document_id into v_doc_aug21;

  insert into public.wbh_source_documents (source_id,source_record_id,request_url,request_method,retrieved_at,http_status,content_sha256,content_type,byte_size,storage_state,transformation_version,notes)
  values ('pbe_curation','wnba_game_1022400239','https://www.wnba.com/game/dal-vs-lva-1022400239','GET',v_now,200,encode(extensions.digest(convert_to('2024-09-19|Dallas Wings|84|Las Vegas Aces|98','UTF8'),'sha256'),'hex'),'text/plain',null,'hash_only','wbh_manual_game_results_v1','Official WNBA game page for the regular-season finale.') returning document_id into v_doc_sep19;

  insert into public.wbh_source_documents (source_id,source_record_id,request_url,request_method,retrieved_at,http_status,content_sha256,content_type,byte_size,storage_state,transformation_version,notes)
  values ('pbe_curation','aces_2024_playoff_results','https://aces.wnba.com/2024-year-in-review-as-it-happens-2','GET',v_now,200,
    encode(extensions.digest(convert_to((select jsonb_agg(x order by x.game_date)::text from jsonb_to_recordset(v_rows) as x(game_date date,away text,away_code text,away_points integer,home text,home_code text,home_points integer,stage_id text,game_type text,season_phase text,counts_for_standings boolean,overtime_periods integer,source_key text) where source_key='aces_year_review'),'UTF8'),'sha256'),'hex'),
    'application/json',null,'hash_only','wbh_manual_game_results_v1','Normalized factual playoff results manually curated from the official Las Vegas Aces 2024 Year in Review page.') returning document_id into v_doc_playoffs;

  insert into public.wbh_ingestion_runs (source_id,adapter_id,adapter_version,transformation_version,mode,as_of,scope)
  values ('pbe_curation','manual_public_game_curation','1.0.0','wbh_manual_game_results_v1','ingest',v_now,jsonb_build_object('dataset',v_dataset,'edition_id','wnba_2024','source_observations',46,'regular_games',40,'playoff_games',6,'expected_preexisting_games',4,'expected_new_games',42,'completeness','score_only','roster_stints_written',0,'player_game_stats_written',0)) returning run_id into v_run;

  for r in select * from jsonb_to_recordset(v_rows) as x(game_date date,away text,away_code text,away_points integer,home text,home_code text,home_points integer,stage_id text,game_type text,season_phase text,counts_for_standings boolean,overtime_periods integer,source_key text) order by game_date,away_code,home_code loop
    v_game_id := 'gm_wnba_2024_'||to_char(r.game_date,'YYYYMMDD')||'_'||r.away_code||'_at_'||r.home_code;
    v_doc := case r.source_key when 'aces_sep19_notes' then v_doc_notes when 'wnba_aug17' then v_doc_aug17 when 'wnba_aug21' then v_doc_aug21 when 'wnba_sep19' then v_doc_sep19 when 'aces_year_review' then v_doc_playoffs else null end;
    if v_doc is null then raise exception 'wbh: unrecognized Aces source key %',r.source_key using errcode='P0001'; end if;
    if not exists(select 1 from public.wbh_team_editions where edition_id='wnba_2024' and display_name=r.away) or not exists(select 1 from public.wbh_team_editions where edition_id='wnba_2024' and display_name=r.home) then raise exception 'wbh: noncanonical team in Aces result % vs %',r.away,r.home using errcode='P0001'; end if;

    if exists(select 1 from public.wbh_games where game_id=v_game_id) then
      if exists(select 1 from public.wbh_games g where g.game_id=v_game_id and (g.edition_id<>'wnba_2024' or g.local_date<>r.game_date or g.stage_id<>r.stage_id or g.status<>'final' or g.game_type<>r.game_type or g.season_phase<>r.season_phase or g.counts_for_standings<>r.counts_for_standings or not g.counts_for_stats or g.overtime_periods<>r.overtime_periods)) then raise exception 'wbh: overlapping canonical game % disagrees with Aces source metadata',v_game_id using errcode='P0001'; end if;
      if not exists(select 1 from public.wbh_game_teams gt join public.wbh_team_editions te on te.team_edition_id=gt.team_edition_id where gt.game_id=v_game_id and gt.side='away' and te.display_name=r.away and gt.points=r.away_points and gt.result=case when r.away_points>r.home_points then 'win' else 'loss' end) or not exists(select 1 from public.wbh_game_teams gt join public.wbh_team_editions te on te.team_edition_id=gt.team_edition_id where gt.game_id=v_game_id and gt.side='home' and te.display_name=r.home and gt.points=r.home_points and gt.result=case when r.home_points>r.away_points then 'win' else 'loss' end) then raise exception 'wbh: overlapping canonical game % disagrees with Aces source teams/scores',v_game_id using errcode='P0001'; end if;
      v_corroborations := v_corroborations + 1;
    else
      insert into public.wbh_games (game_id,edition_id,stage_id,competition_id,local_date,status,game_type,season_phase,counts_for_standings,counts_for_stats,overtime_periods,completeness,source_document_id,ingestion_run_id,transformation_version,derivation)
      values (v_game_id,'wnba_2024',r.stage_id,'wnba',r.game_date,'final',r.game_type,r.season_phase,r.counts_for_standings,true,r.overtime_periods,'score_only',v_doc,v_run,'wbh_manual_game_results_v1',v_derivation);
      insert into public.wbh_game_teams (game_id,team_edition_id,side,points,result,source_document_id,ingestion_run_id,transformation_version,derivation)
      select v_game_id,te.team_edition_id,'away',r.away_points,case when r.away_points>r.home_points then 'win' else 'loss' end,v_doc,v_run,'wbh_manual_game_results_v1',v_derivation from public.wbh_team_editions te where te.edition_id='wnba_2024' and te.display_name=r.away
      union all
      select v_game_id,te.team_edition_id,'home',r.home_points,case when r.home_points>r.away_points then 'win' else 'loss' end,v_doc,v_run,'wbh_manual_game_results_v1',v_derivation from public.wbh_team_editions te where te.edition_id='wnba_2024' and te.display_name=r.home;
      v_new_games := v_new_games + 1;
    end if;

    insert into public.wbh_game_result_evidence (evidence_id,game_id,source_record_id,evidence_role,local_date,away_team_edition_id,home_team_edition_id,away_points,home_points,game_type,stage_id,source_document_id,ingestion_run_id,transformation_version,derivation)
    select 'gre_'||substr(md5(v_dataset||'|'||v_game_id||'|'||r.source_key),1,24),v_game_id,'aces_2024_'||to_char(r.game_date,'YYYYMMDD')||'_'||r.away_code||'_at_'||r.home_code,case when exists(select 1 from public.wbh_games g where g.game_id=v_game_id and g.ingestion_run_id=v_run) then 'origin' else 'corroboration' end,r.game_date,a.team_edition_id,h.team_edition_id,r.away_points,r.home_points,r.game_type,r.stage_id,v_doc,v_run,'wbh_manual_game_results_v1',v_derivation
    from public.wbh_team_editions a, public.wbh_team_editions h where a.edition_id='wnba_2024' and a.display_name=r.away and h.edition_id='wnba_2024' and h.display_name=r.home;
  end loop;

  select count(*) into v_evidence from public.wbh_game_result_evidence where ingestion_run_id=v_run;
  if v_new_games<>42 or v_corroborations<>4 or v_evidence<>46 then raise exception 'wbh: Aces load counts wrong: new %, corroborated %, evidence %; expected 42/4/46',v_new_games,v_corroborations,v_evidence using errcode='P0001'; end if;
  if (select count(*) from public.wbh_games g join public.wbh_game_teams gt on gt.game_id=g.game_id where g.edition_id='wnba_2024' and gt.team_edition_id='te_las_vegas_aces_2024')<>46 or (select count(*) from public.wbh_games g join public.wbh_game_teams gt on gt.game_id=g.game_id where g.edition_id='wnba_2024' and gt.team_edition_id='te_las_vegas_aces_2024' and g.game_type='regular')<>40 or (select count(*) from public.wbh_games g join public.wbh_game_teams gt on gt.game_id=g.game_id where g.edition_id='wnba_2024' and gt.team_edition_id='te_las_vegas_aces_2024' and g.game_type='playoff')<>6 then raise exception 'wbh: Aces final participation verification failed' using errcode='P0001'; end if;

  update public.wbh_ingestion_runs set status='ok',counts=jsonb_build_object('source_observations',46,'new_games',v_new_games,'corroborated_games',v_corroborations,'evidence_rows',v_evidence,'aces_regular_games',40,'aces_playoff_games',6,'roster_stints_written',0,'player_game_stats_written',0) where run_id=v_run;
end $seed$;

commit;
